// One lead per request from the Catálogo B2B "Platica con ventas" form.
// The site validates on its server before posting, so this only shapes a
// clean record with Spanish field names for whatever runs next.
const body = $input.first().json.body || {};
const s = (v) => String(v ?? '').trim();

const tipo = s(body.tipo) === 'Otro' && s(body.tipoOtro)
  ? `Otro: ${s(body.tipoOtro)}`
  : s(body.tipo);

return [{
  json: {
    nombre: s(body.nombre),
    email: s(body.email),
    whatsapp: s(body.whatsapp),
    codigoPostal: s(body.cp),
    consumoMensual: s(body.consumo),
    lineaDeInteres: s(body.linea),
    tipoDeEstablecimiento: tipo,
    enviadoEn: s(body.submittedAt) || new Date().toISOString(),
    origen: 'catalogo-b2b',
  },
}];
